function switchMobileView(type){const table=document.getElementById("vipBudgetTable");const buttons=document.querySelectorAll(".m-tab-btn");if(!table)return;table.className="vip-budget-table view-"+type;buttons.forEach(btn=>btn.classList.remove("active"));if(event&&event.currentTarget){event.currentTarget.classList.add("active")}}var cvView="pers";function renderDoublePieCharts(){var root=document.getElementById("costViz");if(!root)return;var parseVal=function(id){var el=document.getElementById(id);if(!el)return 0;return parseInt((el.textContent||"").replace(/[^0-9]/g,""),10)||0};var sum=function(ids,sfx){return ids.reduce(function(t,i){return t+parseVal("b"+i+"_"+sfx)},0)};var CATS=[{k:"flights",label:"Letenky (dálková + Scoot)",ids:[1,2],c:"var(--c-flights)"},{k:"boat",label:"Loď na Lombok",ids:[3],c:"var(--c-food)"},{k:"hotels",label:"Ubytování a skútry",ids:[4,5],c:"var(--c-hotels)"},{k:"fees",label:"Víza a poplatky",ids:[11,12,13,14],c:"var(--c-fees)"},{k:"food",label:"Jídlo",fn:function(s){return parseVal("bxFood_"+s)},c:"#f59e0b"},{k:"acts",label:"Vstupné a aktivity",fn:function(s){return parseVal("bxAct_"+s)},c:"#a78bfa"}];var DAYS=20;var fmt=function(n){return Math.round(n).toLocaleString("cs-CZ")+" Kč"};var prof={};["pers","fam","sing"].forEach(function(sfx){var o={total:0};CATS.forEach(function(c){o[c.k]=c.fn?c.fn(sfx):sum(c.ids,sfx);o.total+=o[c.k]});var official=parseInt(((document.getElementById("bxGrand_"+sfx)||{}).textContent||"").replace(/[^0-9]/g,""),10);if(official&&Math.abs(official-o.total)>1)console.warn("Kam jdou peníze: součet "+o.total+" ≠ tabulka "+official+" ("+sfx+")");if(official)o.total=official;prof[sfx]=o});if(!prof.pers.total)return;var cur=prof[cvView];var surcharge=prof.sing.total-prof.pers.total;document.getElementById("cvKpis").innerHTML='<div class="cv-kpi"><b>'+fmt(cur.total)+"</b><span>"+(cvView==="pers"?"1 osoba při sdílení pokoje":"sólo cestovatel celkem")+"</span></div>"+'<div class="cv-kpi"><b>'+fmt(cur.total/DAYS)+"</b><span>na osobu a den ("+DAYS+" dní)</span></div>"+'<div class="cv-kpi"><b>'+fmt(prof.fam.total)+"</b><span>pár ve společném pokoji</span></div>"+'<div class="cv-kpi is-warn"><b>+'+fmt(surcharge)+"</b><span>příplatek za cestování sólo</span></div>";var CK=[{label:"CK SEN · 11 dní",days:11,min:81e3,max:108e3},{label:"CK SEN · 20 dní",days:20,min:155e3,max:195e3}];var ourDay=cur.total/DAYS;var scaleMax=Math.max(ourDay,CK.reduce(function(m,c){return Math.max(m,c.max/c.days)},0));var ckMinDay=Math.min.apply(null,CK.map(function(c){return c.min/c.days}));var dayRow=function(label,from,to,sub,isOur){var a=from/scaleMax*100,b=to/scaleMax*100;var val=from===to?fmt(from):fmt(from)+" – "+fmt(to);return'<div class="cv-day-row'+(isOur?" is-our":"")+'">'+'<div class="cv-day-who">'+label+"<small>"+sub+"</small></div>"+'<div class="cv-day-track"><div class="cv-day-fill" style="width:'+a+'%"></div>'+(to>from?'<div class="cv-day-range" style="left:'+a+"%;width:"+(b-a)+'%"></div>':"")+"</div>"+'<div class="cv-day-val">'+val+"<small>na den</small></div></div>"};document.getElementById("cvDay").innerHTML='<div class="cv-day-head"><b>Kolik stojí jeden den</b><span>Na den vycházíme '+(ckMinDay/ourDay).toFixed(1).replace(".",",")+"× levněji než nejlevnější varianta CK SEN.</span></div>"+dayRow("Naše expedice",ourDay,ourDay,(cvView==="pers"?"sdílený pokoj":"sólo")+", "+DAYS+" dní, "+fmt(cur.total),true)+CK.map(function(c){return dayRow(c.label,c.min/c.days,c.max/c.days,fmt(c.min)+" – "+fmt(c.max)+" celkem",false)}).join("");var max=Math.max(prof.pers.total,prof.sing.total);var bar=function(sfx,who){var p=prof[sfx];var segs=CATS.map(function(c){var pct=p.total?p[c.k]/p.total*100:0;var txt=pct>=11?Math.round(p[c.k]/1e3)+" tis.":"";return'<div class="cv-seg" data-k="'+c.k+'" title="'+c.label+": "+fmt(p[c.k])+" ("+Math.round(pct)+' %)" style="flex: 0 0 '+pct+"%; background: "+c.c+';">'+txt+"</div>"}).join("");return'<div class="cv-bar-row'+(sfx===cvView?"":" is-dim")+'"><div class="cv-who">'+who+"</div>"+'<div class="cv-track"><div class="cv-stack" style="width: '+p.total/max*100+'%;">'+segs+"</div></div>"+'<div class="cv-sum">'+fmt(p.total)+"</div></div>"};document.getElementById("cvBars").innerHTML=bar("pers","Sdílený pokoj")+bar("sing","Sólo");document.getElementById("cvCats").innerHTML=CATS.map(function(c){var v=cur[c.k],pct=cur.total?v/cur.total*100:0;var d=prof.sing[c.k]-prof.pers[c.k];var delta=d>0?'<span class="cv-delta">sólo o '+fmt(d)+" víc</span>":'<span class="cv-delta">stejné pro obě varianty</span>';return'<div class="cv-cat" data-k="'+c.k+'" style="--c: '+c.c+';">'+'<div class="cv-n">'+c.label+"</div>"+'<div class="cv-pct">'+Math.round(pct)+" %</div>"+'<div class="cv-kc">'+fmt(v)+"</div>"+'<div class="cv-day">'+fmt(v/DAYS)+" na den</div>"+delta+'<div class="cv-fill" style="width: '+pct+'%;"></div></div>'}).join("")}document.addEventListener("click",function(e){var b=e.target.closest&&e.target.closest(".cv-switch button");if(!b)return;cvView=b.getAttribute("data-cv");[].forEach.call(document.querySelectorAll(".cv-switch button"),function(x){x.setAttribute("aria-pressed",x===b?"true":"false")});renderDoublePieCharts()});document.addEventListener("mouseover",function(e){var root=document.getElementById("costViz");if(!root)return;var t=e.target.closest&&e.target.closest("#costViz [data-k]");root.classList.toggle("has-focus",!!t);[].forEach.call(root.querySelectorAll("[data-k]"),function(x){x.classList.toggle("is-focus",!!t&&x.getAttribute("data-k")===t.getAttribute("data-k"))})});window.addEventListener("load",()=>{setTimeout(renderDoublePieCharts,400)});(function(){var t;function redraw(){clearTimeout(t);t=setTimeout(renderDoublePieCharts,150)}window.addEventListener("load",function(){try{var mo=new MutationObserver(redraw);for(var i=1;i<=14;i++){["pers","fam","sing"].forEach(function(sfx){var e=document.getElementById("b"+i+"_"+sfx);if(e)mo.observe(e,{childList:true,characterData:true,subtree:true})})}["pers","fam","sing"].forEach(function(sfx){["bxFood_","bxAct_","bxGrand_"].forEach(function(pre){var e=document.getElementById(pre+sfx);if(e)mo.observe(e,{childList:true,characterData:true,subtree:true})})});new MutationObserver(redraw).observe(document.documentElement,{attributes:true,attributeFilter:["data-theme"]})}catch(e){}})})();